fn domain_of(s: str) -> str {
    let found = -1
    for k in 0..len(s) {
        if char_at(s, k) == 64 { found = k }
    }
    if found < 0 { s } else { str_slice(s, found + 1, len(s)) }
}

fn cmp_addr(a: str, b: str) -> i64 {
    let c = str_cmp(domain_of(a), domain_of(b))
    if c != 0 { c } else { str_cmp(a, b) }
}

fn add_lines(path: str, d: Dict<str>) -> Result<(), str> {
    let text = read_file(path)?
    let lines = str_split(text, "\n")
    for i in 0..len(lines) {
        let a = str_to_lower(str_trim(lines[i]))
        if len(a) > 0 { dict_set(d, a, "1") }
    }
    Ok(())
}

fn run() -> Result<i64, str> {
    let da = dict_new()
    let db = dict_new()
    add_lines("./data/a.txt", da)?
    add_lines("./data/b.txt", db)?
    let ak = dict_keys(da)
    let bk = dict_keys(db)
    let aonly = 0
    let both = 0
    let bonly = 0
    for k in ak {
        if dict_has(db, k) { both = both + 1 } else { aonly = aonly + 1 }
    }
    let all = ak
    for k in bk {
        if dict_has(da, k) == false {
            bonly = bonly + 1
            all = arr_push(all, k)
        }
    }
    let sorted = arr_sort_by(all, |x, y| cmp_addr(x, y))
    let out = ""
    for i in 0..len(sorted) {
        out = out + sorted[i] + "\n"
    }
    dir_create("./out")?
    write_file("./out/merged.txt", out)?
    println("a-only: {to_str(aonly)}, both: {to_str(both)}, b-only: {to_str(bonly)}")
    Ok(0)
}

fn main() -> i64 {
    match run() {
        Ok(c) => c
        Err(e) => {
            eprintln("error: {e}")
            1
        }
    }
}
